        const a = args[i];
        if (after_ddash) {
            try bindOperand(a, &o, &next_pos, gpa);
            continue;
        }
        if (std.mem.eql(u8, a, "--")) {
            after_ddash = true;
            continue;
        }
        var matched = false;
        if (a.len > 2 and a[0] == '-' and a[1] != '-') {
            var cluster = true;
            for (a[1..]) |ch| {
                var letter_matched = false;
                if (ch == 'S') {
                    if ((seen & (1 << 1)) != 0) {
                        std.debug.print("fx-ls: options '-S' and '-t' are mutually exclusive\n", .{});
                        return error.Conflict;
                    }
                    o.sort = .Size;
                    seen |= 1 << 0;
                    letter_matched = true;
                }
                if (ch == 't') {
                    if ((seen & (1 << 0)) != 0) {
                        std.debug.print("fx-ls: options '-t' and '-S' are mutually exclusive\n", .{});
                        return error.Conflict;
                    }
                    o.sort = .MTime;
                    seen |= 1 << 1;
                    letter_matched = true;
                }
                if (ch == 'l') {
                    o.long = true;
                    seen |= 1 << 2;
                    letter_matched = true;
                }
                if (ch == 'a') {
                    o.all = true;
                    seen |= 1 << 3;
                    letter_matched = true;
                }
                if (!letter_matched) cluster = false;
            }
            if (cluster) continue;
        }
        if (!matched and (std.mem.eql(u8, a, "-S"))) {
            if ((seen & (1 << 1)) != 0) {
                std.debug.print("fx-ls: options '-S' and '-t' are mutually exclusive\n", .{});
                return error.Conflict;
            }
            o.sort = .Size;
            seen |= 1 << 0;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-t"))) {
            if ((seen & (1 << 0)) != 0) {
                std.debug.print("fx-ls: options '-t' and '-S' are mutually exclusive\n", .{});
                return error.Conflict;
            }
            o.sort = .MTime;
            seen |= 1 << 1;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-l") or std.mem.eql(u8, a, "--long"))) {
            o.long = true;
            seen |= 1 << 2;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-a") or std.mem.eql(u8, a, "--all"))) {
            o.all = true;
            seen |= 1 << 3;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "--rows"))) {
            o.rows = true;
            seen |= 1 << 4;
            matched = true;
        }
        if (!matched) {
