fn bindOperand(arg: []const u8, o: *Options, next_pos: *usize, gpa: Allocator) ParseError!void {
    if (next_pos.* == 0) {
        o.path = gpa.dupe(u8, arg) catch return error.OutOfMemory;
        next_pos.* = 1;
        return;
    }
    std.debug.print("fx-ls: unexpected operand '{s}'\n", .{ arg });
    return error.UnexpectedOperand;
}

